#!/usr/bin/env node
import {
  fetchTextWithSsrfGuard
} from "./chunk-XYNQ6JGJ.js";
import {
  atomicWrite
} from "./chunk-MBLQFY4T.js";

// src/services/update-checker.ts
import { readFile, mkdir } from "fs/promises";
import { homedir } from "os";
import { join, dirname } from "path";
var REGISTRY_URL = "https://registry.npmjs.org/@gram-lang/cli/latest";
var CHECK_INTERVAL_MS = 24 * 60 * 60 * 1e3;
function getCachePath() {
  return join(homedir(), ".config", "gram", "update-check.json");
}
async function readCache(cachePath) {
  try {
    const data = JSON.parse(await readFile(cachePath, "utf-8"));
    if (typeof data?.lastCheck === "number" && typeof data?.latestVersion === "string") {
      return data;
    }
    return null;
  } catch {
    return null;
  }
}
async function writeCache(cachePath, cache) {
  await mkdir(dirname(cachePath), { recursive: true });
  await atomicWrite(cachePath, JSON.stringify(cache));
}
async function fetchLatestVersion() {
  const { body } = await fetchTextWithSsrfGuard(REGISTRY_URL);
  const data = JSON.parse(body);
  if (!data.version) {
    throw new Error(`Unexpected response from ${REGISTRY_URL}`);
  }
  return data.version;
}
function isNewerVersion(latest, current) {
  const a = latest.split(".").map(Number);
  const b = current.split(".").map(Number);
  for (let i = 0; i < Math.max(a.length, b.length); i++) {
    const x = a[i] ?? 0;
    const y = b[i] ?? 0;
    if (x !== y) return x > y;
  }
  return false;
}
async function checkForUpdateInBackground(cachePath = getCachePath()) {
  try {
    const cache = await readCache(cachePath);
    if (cache && Date.now() - cache.lastCheck < CHECK_INTERVAL_MS) return;
    const latestVersion = await fetchLatestVersion();
    await writeCache(cachePath, { lastCheck: Date.now(), latestVersion });
  } catch {
  }
}
async function getPendingNotification(currentVersion, cachePath = getCachePath()) {
  const cache = await readCache(cachePath);
  if (!cache) return null;
  return isNewerVersion(cache.latestVersion, currentVersion) ? { latest: cache.latestVersion } : null;
}

export {
  fetchLatestVersion,
  isNewerVersion,
  checkForUpdateInBackground,
  getPendingNotification
};
